225	export function resolveDraftFiles(files: { path: string; target: string }[]): DraftFile[] {
226	  const base = resolve(process.cwd());
227	  // The work tree and /tmp — the pinned interface: a draft is either a file in the
228	  // checkout or an absolute path under /tmp, which is where a conversion step puts its
229	  // output. `/tmp/atomaton-workspace` is the one subdirectory of it that survives a run.
230	  const roots = [base, TMP_ROOT];
231	  const seen = new Set<string>();
232	  const out: DraftFile[] = [];
